#include <iostream>
#include <string>
#include <vector>

struct Registro { std::string tipo; int bytes; };

struct Totales { int texturas=0; int mallas=0; int sonidos=0; int bytes=0; };

// Cada elemento del vector ya fue admitido. Completa sólo esta función.
Totales contar_tipos(const std::vector<Registro>& admitidos) {
    Totales total;
    // Cuenta cada tipo exacto y suma bytes declarados.
    return total;
}

int main() {
    int grupos=0;

    if (!(std::cin >> grupos)) return 0;

    for (int g=0; g<grupos; ++g) {
        int cantidad=0;
        if (!(std::cin >> cantidad)) return 1;
        std::vector<Registro> admitidos;

        for (int i=0; i<cantidad; ++i) {
            Registro r;
            if (!(std::cin >> r.tipo >> r.bytes)) return 1;
            admitidos.push_back(r);
        }

        const Totales t=contar_tipos(admitidos);

        std::cout << "textura=" << t.texturas << " malla=" << t.mallas
                  << " sonido=" << t.sonidos << " bytes=" << t.bytes << '\n';
    }
}

