$cuerpoEstadisticas = @'
#include "assetcheck/estadisticas.hpp"

#include <locale>
#include <sstream>

namespace assetcheck {

Estadisticas contar_tipos(const Lote& lote) {
    Estadisticas total{};
    for (const auto& admision : lote.admitidos) {
        const Registro& registro = admision.registro;
        if (registro.tipo == "textura") {
            ++total.texturas;
        } else if (registro.tipo == "malla") {
            ++total.mallas;
        } else if (registro.tipo == "sonido") {
            ++total.sonidos;
        }
        total.bytes_total += registro.tamano_bytes;
    }
    return total;
}

std::string salida_tipos(const Estadisticas& datos, const Lote& lote) {
    std::ostringstream salida;
    salida.imbue(std::locale::classic());
    salida << "TIPOS textura=" << datos.texturas
           << " malla=" << datos.mallas
           << " sonido=" << datos.sonidos
           << " bytes_total=" << datos.bytes_total << '\n';
    salida << "RESUMEN lineas=" << lote.admitidos.size() + lote.rechazados.size()
           << " aceptados=" << lote.admitidos.size()
           << " rechazados=" << lote.rechazados.size() << '\n';
    return salida.str();
}

} // namespace assetcheck
'@
Set-Content -LiteralPath $rutaFuente -Value $cuerpoEstadisticas -Encoding UTF8
if (-not $?) { throw 'No se pudo guardar la fuente UTF8.' }

$rutaCMake = (Resolve-Path -LiteralPath '.\CMakeLists.txt' -ErrorAction Stop).Path
if (-not (Test-Path -LiteralPath '.\src\estadisticas.cpp' -PathType Leaf) -or
    -not (Test-Path -LiteralPath '.\include\assetcheck\estadisticas.hpp' -PathType Leaf)) {
    throw 'Faltan las fuentes de estadisticas. Revisa la carpeta AssetCheck y completa la etapa anterior.'
}
$bytesCMake = [IO.File]::ReadAllBytes($rutaCMake)
$codigoCMake = Get-Content -LiteralPath $rutaCMake -Raw -Encoding UTF8
if ($codigoCMake.Contains('assetcheck_estadisticas')) {
    throw 'El objetivo de estadisticas ya aparece. Revisa CMakeLists.txt sin anadirlo otra vez.'
}
$anclaCMake = 'target_compile_features(assetcheck_manifiesto PUBLIC cxx_std_23)'
$primera = $codigoCMake.IndexOf($anclaCMake, [StringComparison]::Ordinal)
$ultima = $codigoCMake.LastIndexOf($anclaCMake, [StringComparison]::Ordinal)
if ($primera -lt 0 -or $primera -ne $ultima) {
    throw 'El final de la biblioteca manifiesto debe aparecer exactamente una vez. Revisa el archivo sin sobrescribirlo.'
}
$primerPrograma = $codigoCMake.IndexOf('add_executable(', [StringComparison]::Ordinal)
if ($primerPrograma -lt 0 -or $primerPrograma -le $primera) {
    throw 'Se esperaba manifiesto antes de los programas. Conserva y revisa el orden de los objetivos.'
}
if ($codigoCMake.Contains("`r`n")) { $saltoCMake = "`r`n" } else { $saltoCMake = "`n" }
$ordenesCMake = @(
    'add_library(assetcheck_estadisticas STATIC src/estadisticas.cpp)'
    'target_include_directories(assetcheck_estadisticas PUBLIC include)'
    'target_link_libraries(assetcheck_estadisticas PUBLIC assetcheck_lote)'
    'target_compile_features(assetcheck_estadisticas PUBLIC cxx_std_23)'
)
$insercionCMake = $saltoCMake + $saltoCMake + [string]::Join($saltoCMake, $ordenesCMake)
$codigoCMake = $codigoCMake.Replace($anclaCMake, $anclaCMake + $insercionCMake)
$teniaBOM = $bytesCMake.Length -ge 3 -and $bytesCMake[0] -eq 239 -and $bytesCMake[1] -eq 187 -and $bytesCMake[2] -eq 191
$codificacionCMake = [Text.UTF8Encoding]::new($teniaBOM)
[IO.File]::WriteAllText($rutaCMake, $codigoCMake, $codificacionCMake)

