#include "assetcheck/estadisticas.hpp"
#include "assetcheck/manifiesto.hpp"
#include <iostream>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "ERROR causa=APERTURA\n";
        return 2;
